def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    if "ERPNext" in json.dumps({"l": lessons, "q": questions}):
        problems.append(f"  {name}: ERPNext branding leakage")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.155.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.154.0"' not in init:
        sys.exit("ABORT: not at v3.154.0.")
    for k in ("terminal_estate", "shift_sale"):
        if k not in data:
            sys.exit(f"ABORT: {k} module not found in data file.")

    problems = _validate("POS3", LESSONS_M3, QUESTIONS_M3, 9) + _validate("POS4", LESSONS_M4, QUESTIONS_M4, 9)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    for name, lessons, questions, key, desc in (
        ("POS 3", LESSONS_M3, QUESTIONS_M3, "terminal_estate",
         "Installing and managing terminals: the installer and sync service, the four-step wizard with the branch lock, activation and licensing with the mode precedence rule, printer/drawer/display configuration tested with real sales, terminal settings and label templates, cached cashiers and the leaver procedure, and the device register with revocation and the monthly last-seen review."),
        ("POS 4", LESSONS_M4, QUESTIONS_M4, "shift_sale",
         "The trading day: sign-in and the top-bar indicators, opening the shift with a counted float, building sales with stack/queue and the line markers, batches/serials/units done accurately, customers, loyalty and the credit suspension, hold versus clear and every payment method's rules, receipts, the gift voucher sale and the till lock, and closing the shift against pre-filled figures that are counted, overwritten and explained."),
    ):
        bank = rebalance(list(questions))
        dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
        if max(dist.values()) > 10:
            print(f"ABORT — {name} spread failed: {dist}")
            sys.exit(1)
        total = sum(len(l["html"]) for l in lessons)
        print(f"{name} v2: {len(lessons)} chapters ({total:,} chars, min {min(len(l['html']) for l in lessons):,}), bank {len(bank)}, spread {dist}")
        if not CHECK_ONLY:
            data[key]["lessons"] = lessons
            data[key]["questions"] = bank
            data[key]["desc"] = desc

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.154.0"', '"3.155.0"'))
    print("  data: POS 3 + POS 4 lessons + banks REPLACED (style v2.1)")
    print("wrote __version__ -> 3.155.0")


if __name__ == "__main__":
    main()
